using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using GymApi.Data;
using GymApi.Dtos;
using GymApi.Models;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.IdentityModel.Tokens;
namespace GymApi.Services;
public interface IAuthService { Task<AuthResponseDto?> LoginAsync(LoginDto dto); }
public interface IMemberService { Task<MemberDto> RegisterAsync(RegisterDto dto); Task<List<MemberDto>> GetAllAsync(); Task<MemberDto> GetAsync(int id); Task<MemberDto> UpdateAsync(int id, MemberUpdateDto dto); Task<MemberDto> RenewAsync(int id, string plan); Task DeactivateAsync(int id); }
public interface IClassService { Task<List<GymClassDto>> GetAllAsync(); Task<GymClassDto> SaveAsync(int? id, GymClassInputDto dto); Task CancelAsync(int id); Task<List<InstructorDto>> GetInstructorsAsync(); Task<List<ReservationDto>> RosterAsync(int id); }
public interface IReservationService { Task<List<ReservationDto>> GetAsync(ClaimsPrincipal user); Task<ReservationDto> GetOneAsync(int id, ClaimsPrincipal user); Task<ReservationDto> CreateAsync(int classId, ClaimsPrincipal user); Task<ReservationDto> ChangeAsync(int id, string status, ClaimsPrincipal user); }
public interface IReportService { Task<List<OverdueMemberDto>> OverdueAsync(); Task<List<ClassAttendanceDto>> AttendanceAsync(); }
public class AuthService(AppDbContext db, IPasswordHasher<UserAccount> hasher, IConfiguration config) : IAuthService
{
    public async Task<AuthResponseDto?> LoginAsync(LoginDto dto) { var u = await db.UserAccounts.FirstOrDefaultAsync(x => x.Username == dto.Username); if (u == null || u.Status != AccountStatus.Active || hasher.VerifyHashedPassword(u, u.PasswordHash, dto.Password) == PasswordVerificationResult.Failed) return null; if (u.Role == Roles.Member && !await db.Members.AnyAsync(m => m.UserAccountId == u.Id && m.IsActive)) return null; var claims = new[] { new Claim(ClaimTypes.NameIdentifier, u.Id.ToString()), new Claim(ClaimTypes.Name, u.Username), new Claim(ClaimTypes.Role, u.Role) }; var key = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(config["Jwt:Key"]!)); var token = new JwtSecurityToken(config["Jwt:Issuer"], config["Jwt:Audience"], claims, expires: DateTime.UtcNow.AddMinutes(config.GetValue<int>("Jwt:ExpiryMinutes", 60)), signingCredentials: new SigningCredentials(key, SecurityAlgorithms.HmacSha256)); return new AuthResponseDto(new JwtSecurityTokenHandler().WriteToken(token), u.Username, u.FullName, u.Role); }
}
public class MemberService(AppDbContext db, IPasswordHasher<UserAccount> hasher) : IMemberService
{
    private async Task<MemberDto> Map(Member m) { var ss = await db.Subscriptions.Include(s => s.Plan).Where(s => s.MemberId == m.Id).ToListAsync(); var sum = MembershipHelper.Summarize(m.IsActive, ss); return new(m.Id, m.GetFullName(), m.UserAccount?.Username ?? "", m.Email, m.ContactNumber, sum.PlanName, sum.ExpiresOn, sum.Status, m.IsActive); }
    public async Task<MemberDto> RegisterAsync(RegisterDto d) { if (await db.UserAccounts.AnyAsync(x => x.Username == d.Username)) throw new ArgumentException("Username is already taken."); var plan = await db.MembershipPlans.FirstOrDefaultAsync(p => p.PlanName == d.MembershipPlan); if (plan == null) throw new ArgumentException("Choose Monthly, Quarterly, or Annual."); var names = d.FullName.Trim().Split(' ', 2); var u = new UserAccount { Username = d.Username.Trim(), FullName = d.FullName.Trim(), Role = Roles.Member, Status = AccountStatus.Active }; u.PasswordHash = hasher.HashPassword(u, d.Password); var m = new Member { UserAccount = u, FirstName = names[0], LastName = names.Length > 1 ? names[1] : "Member", Email = d.Email, ContactNumber = d.Phone ?? "", IsActive = true, DateRegistered = DateTime.Today }; db.Members.Add(m); await db.SaveChangesAsync(); db.Subscriptions.Add(new Subscription { MemberId = m.Id, PlanId = plan.Id, StartDate = DateTime.Today, ExpirationDate = DateTime.Today.AddDays(plan.DurationDays), Status = SubscriptionStatus.Active }); await db.SaveChangesAsync(); return await Map(await db.Members.Include(x => x.UserAccount).FirstAsync(x => x.Id == m.Id)); }
    public async Task<List<MemberDto>> GetAllAsync() { var ms = await db.Members.Include(x => x.UserAccount).ToListAsync(); var list = new List<MemberDto>(); foreach (var m in ms) list.Add(await Map(m)); return list; }
    public async Task<MemberDto> GetAsync(int id) { var m = await db.Members.Include(x => x.UserAccount).FirstOrDefaultAsync(x => x.Id == id) ?? throw new GymApi.Exceptions.NotFoundException("Member not found."); return await Map(m); }
    public async Task<MemberDto> UpdateAsync(int id, MemberUpdateDto d) { var m = await db.Members.Include(x => x.UserAccount).FirstOrDefaultAsync(x => x.Id == id) ?? throw new GymApi.Exceptions.NotFoundException("Member not found."); var a = d.FullName.Trim().Split(' ', 2); m.FirstName = a[0]; m.LastName = a.Length > 1 ? a[1] : "Member"; m.Email = d.Email; m.ContactNumber = d.Phone ?? ""; m.IsActive = d.IsActive; await db.SaveChangesAsync(); return await Map(m); }
    public async Task<MemberDto> RenewAsync(int id, string planName) { var m = await db.Members.FindAsync(id) ?? throw new GymApi.Exceptions.NotFoundException("Member not found."); var p = await db.MembershipPlans.FirstOrDefaultAsync(x => x.PlanName == planName) ?? throw new ArgumentException("Invalid membership plan."); var today = DateTime.Today; var last = await db.Subscriptions.Where(s => s.MemberId == id && s.Status == SubscriptionStatus.Active).OrderByDescending(s => s.ExpirationDate).FirstOrDefaultAsync(); var start = last != null && last.ExpirationDate >= today ? last.ExpirationDate.AddDays(1) : today; db.Subscriptions.Add(new Subscription { MemberId = id, PlanId = p.Id, StartDate = start, ExpirationDate = start.AddDays(p.DurationDays), Status = SubscriptionStatus.Active }); await db.SaveChangesAsync(); return await GetAsync(id); }
    public async Task DeactivateAsync(int id) { var m = await db.Members.FindAsync(id) ?? throw new GymApi.Exceptions.NotFoundException("Member not found."); m.IsActive = false; foreach (var r in await db.Reservations.Where(r => r.MemberId == id && (r.Status == ReservationStatus.Reserved || r.Status == ReservationStatus.Confirmed)).ToListAsync()) r.Status = ReservationStatus.Cancelled; await db.SaveChangesAsync(); }
}
public class ClassService(AppDbContext db) : IClassService
{
    private async Task<GymClassDto> Map(ClassSchedule c) { var rs = await db.Reservations.Where(r => r.ClassScheduleId == c.Id && r.Status != ReservationStatus.Cancelled).CountAsync(); var inst = c.InstructorId.HasValue ? await db.UserAccounts.FindAsync(c.InstructorId.Value) : null; return new(c.Id, c.ClassName, null, c.InstructorId, inst?.FullName ?? "Unassigned", c.GetStart(), (int)(c.EndTime - c.StartTime).TotalMinutes, c.Capacity, rs, Math.Max(0, c.Capacity - rs), c.Status); }
    public async Task<List<GymClassDto>> GetAllAsync() { var list = new List<GymClassDto>(); foreach (var c in await db.ClassSchedules.OrderBy(c => c.ClassDate).ThenBy(c => c.StartTime).ToListAsync()) list.Add(await Map(c)); return list; }
    public async Task<GymClassDto> SaveAsync(int? id, GymClassInputDto d) { if (d.DurationMinutes < 15 || d.DurationMinutes > 240 || d.Capacity < 1) throw new ArgumentException("Invalid duration or capacity."); var c = id.HasValue ? await db.ClassSchedules.FindAsync(id.Value) : new ClassSchedule(); if (c == null) throw new GymApi.Exceptions.NotFoundException("Class not found."); if (!await db.UserAccounts.AnyAsync(u => u.Id == d.InstructorId && u.Role == Roles.Instructor)) throw new ArgumentException("Choose a valid instructor."); c.ClassName = d.Name.Trim(); c.InstructorId = d.InstructorId; c.ClassDate = d.StartTime.Date; c.StartTime = d.StartTime.TimeOfDay; c.EndTime = c.StartTime.Add(TimeSpan.FromMinutes(d.DurationMinutes)); c.Capacity = d.Capacity; c.Status = ClassStatus.Open; if (!id.HasValue) db.ClassSchedules.Add(c); await db.SaveChangesAsync(); return await Map(c); }
    public async Task CancelAsync(int id) { var c = await db.ClassSchedules.FindAsync(id) ?? throw new GymApi.Exceptions.NotFoundException("Class not found."); c.Status = ClassStatus.Cancelled; foreach (var r in await db.Reservations.Where(r => r.ClassScheduleId == id && (r.Status == ReservationStatus.Reserved || r.Status == ReservationStatus.Confirmed)).ToListAsync()) r.Status = ReservationStatus.Cancelled; await db.SaveChangesAsync(); }
    public async Task<List<InstructorDto>> GetInstructorsAsync() => await db.UserAccounts.Where(u => u.Role == Roles.Instructor && u.Status == AccountStatus.Active).Select(u => new InstructorDto(u.Id, u.FullName)).ToListAsync();
    public async Task<List<ReservationDto>> RosterAsync(int id) => await db.Reservations.Include(r => r.Member).Include(r => r.ClassSchedule).Where(r => r.ClassScheduleId == id).Select(r => new ReservationDto(r.Id, r.Member!.GetFullName(), r.ClassSchedule!.ClassName, r.ClassSchedule.GetStart(), r.Status, r.ReservationDate, Array.Empty<string>())).ToListAsync();
}
public class ReservationService(AppDbContext db) : IReservationService
{
    private int UserId(ClaimsPrincipal u) => int.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!);
    private async Task<ReservationDto> Map(Reservation r, ClaimsPrincipal user) { var m = await db.Members.FindAsync(r.MemberId); var c = await db.ClassSchedules.FindAsync(r.ClassScheduleId); var role = user.FindFirstValue(ClaimTypes.Role); var allowed = ReservationStatus.NextStatuses(r.Status).Where(s => role != Roles.Member || s == ReservationStatus.Cancelled).ToArray(); return new(r.Id, m?.GetFullName() ?? "", c?.ClassName ?? "", c?.GetStart() ?? DateTime.MinValue, r.Status, r.ReservationDate, allowed); }
    public async Task<List<ReservationDto>> GetAsync(ClaimsPrincipal u) { var q = db.Reservations.Include(r => r.Member).Include(r => r.ClassSchedule).AsQueryable(); var role = u.FindFirstValue(ClaimTypes.Role); if (role == Roles.Member) { var m = await db.Members.FirstOrDefaultAsync(x => x.UserAccountId == UserId(u)); q = q.Where(r => m != null && r.MemberId == m.Id); } var list = await q.ToListAsync(); var result = new List<ReservationDto>(); foreach (var r in list) result.Add(await Map(r, u)); return result; }
    public async Task<ReservationDto> GetOneAsync(int id, ClaimsPrincipal u) { var r = await db.Reservations.FindAsync(id) ?? throw new GymApi.Exceptions.NotFoundException("Reservation not found."); if (u.IsInRole(Roles.Member) && !await db.Members.AnyAsync(m => m.Id == r.MemberId && m.UserAccountId == UserId(u))) throw new GymApi.Exceptions.ForbiddenException("You can only view your own reservation."); return await Map(r, u); }
    public async Task<ReservationDto> CreateAsync(int classId, ClaimsPrincipal u) { var m = await db.Members.FirstOrDefaultAsync(x => x.UserAccountId == UserId(u) && x.IsActive) ?? throw new GymApi.Exceptions.ForbiddenException("Active member profile required."); var c = await db.ClassSchedules.FindAsync(classId) ?? throw new GymApi.Exceptions.NotFoundException("Class not found."); var sub = await db.Subscriptions.Where(s => s.MemberId == m.Id && s.Status == SubscriptionStatus.Active && s.StartDate <= DateTime.Today && s.ExpirationDate >= DateTime.Today).AnyAsync(); if (!sub) throw new GymApi.Exceptions.BusinessRuleException("An active membership is required to book."); if (c.Status != ClassStatus.Open || c.GetStart() <= DateTime.Now) throw new GymApi.Exceptions.BusinessRuleException("This class is not available for booking."); if (await db.Reservations.AnyAsync(r => r.MemberId == m.Id && r.ClassScheduleId == classId && r.Status != ReservationStatus.Cancelled)) throw new GymApi.Exceptions.BusinessRuleException("You already booked this class."); if (await db.Reservations.CountAsync(r => r.ClassScheduleId == classId && r.Status != ReservationStatus.Cancelled) >= c.Capacity) throw new GymApi.Exceptions.BusinessRuleException("This class is full."); var r = new Reservation { MemberId = m.Id, ClassScheduleId = classId }; db.Reservations.Add(r); await db.SaveChangesAsync(); return await Map(r, u); }
    public async Task<ReservationDto> ChangeAsync(int id, string status, ClaimsPrincipal u) { var r = await db.Reservations.FindAsync(id) ?? throw new GymApi.Exceptions.NotFoundException("Reservation not found."); if (u.IsInRole(Roles.Member) && (!await db.Members.AnyAsync(m => m.Id == r.MemberId && m.UserAccountId == UserId(u)) || status != ReservationStatus.Cancelled)) throw new GymApi.Exceptions.ForbiddenException("Members may only cancel their own reservations."); if (!ReservationStatus.CanMove(r.Status, status)) throw new GymApi.Exceptions.BusinessRuleException("Invalid reservation status transition."); r.Status = status; await db.SaveChangesAsync(); return await Map(r, u); }
}
public class ReportService(AppDbContext db) : IReportService
{
    public async Task<List<OverdueMemberDto>> OverdueAsync() { var list = new List<OverdueMemberDto>(); var ms = await db.Members.Include(m => m.UserAccount).ToListAsync(); foreach (var m in ms) { var s = await db.Subscriptions.Include(x => x.Plan).Where(x => x.MemberId == m.Id && x.Status == SubscriptionStatus.Active).OrderByDescending(x => x.ExpirationDate).FirstOrDefaultAsync(); if (s != null && s.ExpirationDate < DateTime.Today) list.Add(new(m.GetFullName(), m.Email, s.Plan?.PlanName, s.ExpirationDate, (DateTime.Today - s.ExpirationDate).Days)); } return list; }
    public async Task<List<ClassAttendanceDto>> AttendanceAsync() { var result = new List<ClassAttendanceDto>(); foreach (var c in await db.ClassSchedules.ToListAsync()) { var rs = await db.Reservations.Where(r => r.ClassScheduleId == c.Id).ToListAsync(); result.Add(new(c.ClassName, c.GetStart(), c.Capacity, rs.Count(r => r.Status == ReservationStatus.Reserved), rs.Count(r => r.Status == ReservationStatus.Confirmed), rs.Count(r => r.Status == ReservationStatus.Attended), rs.Count(r => r.Status == ReservationStatus.Cancelled))); } return result; }
}
